-- Run only after applying and generating the invoice-drafts migration locally.
begin;
create function pg_temp.check_draft(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function pg_temp.expect_draft(statement text,code text,label text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=code then raise notice 'PASS: %',label;return;end if;raise;end;raise exception 'FAIL: %',label;end$$;
insert into auth.users(id) values ('60100000-0000-4000-8000-000000000001'),('60100000-0000-4000-8000-000000000002');
insert into access_private.mutation_keys values('synthetic-draft-test',decode(repeat('ac',32),'hex'));
insert into public.properties values('hu60-draft-property','60100000-0000-4000-8000-000000000001','{}','2026-10-13T00:00:00Z');
create function pg_temp.draft_ticket(m jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare msg text;begin msg=(jsonb_build_object('keyId','synthetic-draft-test','expires',floor(extract(epoch from clock_timestamp()))+120,'actor',auth.uid(),'inputHash','synthetic-draft','module','expense:draft','audit','{}'::jsonb,'kind','draft','properties','[{"id":"hu60-draft-property","version":"2026-10-13T00:00:00Z"}]'::jsonb)||m)::text;return public.commit_validated_owner_change(msg,encode(extensions.hmac(convert_to(msg,'UTF8'),decode(repeat('ac',32),'hex'),'sha256'),'hex'));end$$;
select set_config('request.jwt.claim.sub','60100000-0000-4000-8000-000000000001',true);
set local role authenticated;
select pg_temp.check_draft(pg_temp.draft_ticket('{"requestId":"create-draft","draft":{"id":"hu60-draft-a","propertyId":"hu60-draft-property","status":"Borrador","invoice":{"number":"INV-A","supplierId":"supplier-a","declaredTotal":10,"lines":[{"description":"Blue paint"}]}}}')->>'id'='hu60-draft-a','draft stored with owner session');
select pg_temp.check_draft((pg_temp.draft_ticket('{"requestId":"create-draft","draft":{"id":"hu60-draft-a","propertyId":"hu60-draft-property","status":"Borrador","invoice":{"number":"INV-A","supplierId":"supplier-a","declaredTotal":10,"lines":[{"description":"Blue paint"}]}}}')->>'replayed')::boolean and (select count(*)=1 from public.expense_drafts),'retry does not duplicate');
select pg_temp.expect_draft($q$select pg_temp.draft_ticket('{"requestId":"stale-draft","draft":{"id":"hu60-draft-a","propertyId":"hu60-draft-property","status":"Borrador"}}')$q$,'40001','stale draft version denied');
select pg_temp.check_draft(jsonb_array_length(public.owner_invoice_draft_list('hu60-draft-property',search_text=>'paint')->'drafts')=1,'description filter returns matching draft');
select pg_temp.check_draft(jsonb_array_length(public.owner_invoice_draft_list('hu60-draft-property',supplier_filter=>'other')->'drafts')=0,'supplier filter excludes nonmatches');
select pg_temp.check_draft(not has_function_privilege('anon','public.owner_invoice_draft_list(text,text,text,date,date,text,integer)','execute') and not has_table_privilege('authenticated','public.expense_drafts','insert'),'no anonymous listing or direct draft insertion');
select set_config('request.jwt.claim.sub','60100000-0000-4000-8000-000000000002',true);
select pg_temp.check_draft(jsonb_array_length(public.owner_invoice_draft_list('hu60-draft-property')->'drafts')=0,'other owner cannot list drafts');
select set_config('request.jwt.claim.sub','60100000-0000-4000-8000-000000000001',true);
reset role;
create function pg_temp.fail_draft_audit() returns trigger language plpgsql as $$begin if new.id like '%:draft-fail' then raise exception using errcode='P0001',message='synthetic draft audit failure';end if;return new;end$$;
create trigger hu60_draft_fail before insert on public.audit_events for each row execute function pg_temp.fail_draft_audit();
set local role authenticated;
select pg_temp.expect_draft($q$select pg_temp.draft_ticket('{"requestId":"draft-fail","draft":{"id":"hu60-draft-fail","propertyId":"hu60-draft-property","status":"Borrador"}}')$q$,'P0001','draft audit failure propagates');
select pg_temp.check_draft(not exists(select 1 from public.expense_drafts where id='hu60-draft-fail'),'draft rolled back with failed audit');
reset role;
insert into public.expense_invoices(user_id,id,position,request_id,payload) values('60100000-0000-4000-8000-000000000001','hu60-draft-issued',0,'hu60-draft-a','{"declaredTotal":10}');
set local role authenticated;
select pg_temp.expect_draft($q$select pg_temp.draft_ticket(jsonb_build_object('requestId','issued','draftVersion',(select updated_at from public.expense_drafts where id='hu60-draft-a'),'draft','{"id":"hu60-draft-a","propertyId":"hu60-draft-property","status":"Borrador"}'::jsonb))$q$,'40001','issued invoice prevents draft changes');
reset role;
insert into public.expense_drafts(user_id,id,property_id,status,payload,updated_at) select '60100000-0000-4000-8000-000000000001','hu60-draft-page-'||lpad(n::text,4,'0'),'hu60-draft-property','Borrador','{}','2026-10-13T00:00:00Z' from generate_series(1,2999) n;
set local role authenticated;
select pg_temp.check_draft(jsonb_array_length(public.owner_invoice_draft_list('hu60-draft-property')->'drafts')=25 and (public.owner_invoice_draft_list('hu60-draft-property')->>'more')::boolean,'listing bounded to 25 plus more flag');
select pg_temp.expect_draft($q$select pg_temp.draft_ticket('{"requestId":"over-limit","draft":{"id":"hu60-draft-over-limit","propertyId":"hu60-draft-property","status":"Borrador"}}')$q$,'40001','3000 draft limit enforced in transaction');
reset role;
rollback;
